#!/usr/bin/env python3
"""Read-only recomputation of retained measurements; no server or load operations."""
import hashlib,json,statistics
from collections import defaultdict
from pathlib import Path
BASE=Path('/tmp/forge-improvement-20261003')
DOC=Path('/home/helloworld0822/coding/forge/docs')
ART=BASE/'.omo/teams/forge-codex-review-20261003/artifacts'
FILES={'final40':'verified-posts','poll20':'poll-control','historical60':'diagnosis','sql':'verified-checks-and-sql'}
data={k:json.loads((BASE/(v+'.json')).read_text()) for k,v in FILES.items()}
metric_names=['rps','p95_ms','cpu_core_percent','db_cpu_core_percent','client_cpu_core_percent','peak_threads','memory_mib']
def stats(values):
 return {'median':statistics.median(values),'min':min(values),'max':max(values)}
result={'method':'Per-trial medians/min/max; SQL excludes first of seven identically per phase; paired ratios match repeat, endpoint, concurrency.', 'raw_sha256':{},'datasets':{}}
for key,expected in [('final40',40),('poll20',20),('historical60',60)]:
 d=data[key];rows=d['results'];assert len(rows)==expected
 assert sum(r['errors'] for r in rows)==0
 assert sum(r['server_cpu_delta']['nr_throttled'] for r in rows)==0
 groups=defaultdict(list)
 for r in rows:
  groups[(r['config']['name'],r['endpoint'],r['concurrency'])].append(r)
  if 'profile' in r:
   p=r['profile'];assert p['requests']==p['queries']==sum(p['worker_requests']);assert not p['worker_requests'][-1]
   if key != 'historical60': assert p['requests']==r['requests']
 out={'trials':len(rows),'requests':sum(r['requests'] for r in rows),'errors':0,'nr_throttled':0,'groups':{}}
 for (name,endpoint,c),rr in groups.items():
  g={m:stats([r[m] for r in rr]) for m in metric_names};g['repeats']=len(rr)
  g['max_individual_client_cpu_percent']=max(x for r in rr for x in r['client_process_cpu_core_percent'])
  if 'profile' in rr[0]:
   g['profile_us']={m:stats([r['profile'][m]/r['profile']['requests']/1000 for r in rr]) for m in ['handler_ns','cpu_ns','acquire_ns','query_ns']}
   g['acquire_percent_of_handler']=stats([r['profile']['acquire_ns']/r['profile']['handler_ns']*100 for r in rr])
   g['query_percent_of_handler']=stats([r['profile']['query_ns']/r['profile']['handler_ns']*100 for r in rr])
   g['active_lifetime_thread_bins']=[sum(x>0 for x in r['profile']['worker_requests']) for r in rr]
   g['highest_nonzero_lifetime_thread_bin']=max(i for r in rr for i,x in enumerate(r['profile']['worker_requests']) if x)
  out['groups'][f'{name}|{endpoint}|{c}']=g
 if 'cpu_observation_seconds'in rows[0]:
  out['cpu_observation_seconds']=stats([r['cpu_observation_seconds'] for r in rows])
  out['request_elapsed_seconds']=stats([r['seconds'] for r in rows])
  out['max_client_start_lateness_ms']=max(x for r in rows for x in r['client_start_lateness_ms'])
 result['datasets'][key]=out
assert data['final40']['runtime_image_id']==data['poll20']['runtime_image_id']==data['sql']['image_id']
for k in ['candidate_web_source_sha256','profile_source_sha256','load_source_sha256']:
 assert data['final40'][k]==data['poll20'][k]
assert data['final40']['binary_sha256']['portfolio-fixed-profile']==data['poll20']['binary_sha256']['portfolio-fixed-profile']
assert data['final40']['binary_sha256']['portfolio-fixed']==data['sql']['binary_sha256']
result['comparisons']={}
for key,a,b in [('final40','profile_fixed_connection','profile_fixed_pool'),('final40','plain_fixed_connection','rust'),('poll20','profile_fixed_connection','profile_fixed_pool_poll')]:
 rows=data[key]['results']
 for c in [16,64]:
  aa={r['repeat']:r for r in rows if r['config']['name']==a and r['concurrency']==c}
  bb={r['repeat']:r for r in rows if r['config']['name']==b and r['concurrency']==c};assert aa.keys()==bb.keys()
  ratios=[aa[i]['rps']/bb[i]['rps'] for i in sorted(aa)]
  ga=result['datasets'][key]['groups'][f'{a}|/api/posts|{c}'];gb=result['datasets'][key]['groups'][f'{b}|/api/posts|{c}']
  result['comparisons'][f'{key}|{a}/{b}|{c}']={'rps_ratio_of_medians':ga['rps']['median']/gb['rps']['median'],'paired_rps_ratio':stats(ratios),'paired_rps_ratios':ratios,'p95_ratio_of_medians':ga['p95_ms']['median']/gb['p95_ms']['median'],'paired_p95_ratio':stats([aa[i]['p95_ms']/bb[i]['p95_ms'] for i in sorted(aa)])}
result['sql_execution_ms']={phase:{q:stats([p['Execution Time'] for p in plans[1:]]) for q,plans in qq.items()} for phase,qq in data['sql']['plans'].items()}
for key,name in FILES.items():
 source=BASE/(name+'.json');dest=DOC/('performance-improvements-'+name+'.json');dest.write_bytes(source.read_bytes())
 result['raw_sha256'][dest.name]=hashlib.sha256(dest.read_bytes()).hexdigest()
(ART/'statistics-B.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({k:{x:v[x] for x in ['trials','requests','errors','nr_throttled']} for k,v in result['datasets'].items()},indent=2))
